/**
 * Handshake's copy of CyberSpec's recorded interface samples, with every recording replaced by 10 ms of silence.
 * CyberSpec ships recordings here (three from Epidemic Sound, two with no documented licence) that its own notice
 * excludes from its MIT licence and gives no right to redistribute (THIRD_PARTY_NOTICES.md). Jali's repository and
 * its hosted examples are public, so the recordings are not in them. The keys, rates and format are CyberSpec's, so
 * sound.ts is unchanged: the recorded cues are silent, and its synthesised sounds play as before. Interface sounds
 * are off by default. Re-vendoring from the registry brings the recordings back: replace this file again.
 */
const SILENCE = ""

const soundSamples = {
  hover: { sampleRate: 48000, pcm: SILENCE },
  adjust: { sampleRate: 48000, pcm: SILENCE },
  decrement: { sampleRate: 48000, pcm: SILENCE },
  increment: { sampleRate: 48000, pcm: SILENCE },
  on: { sampleRate: 48000, pcm: SILENCE },
  off: { sampleRate: 48000, pcm: SILENCE },
  modalOpen: { sampleRate: 48000, pcm: SILENCE },
  modalCloseBase: { sampleRate: 48000, pcm: SILENCE },
  drawerOpen: { sampleRate: 48000, pcm: SILENCE },
  drawerCloseBase: { sampleRate: 48000, pcm: SILENCE },
  drawerCloseShortBase: { sampleRate: 48000, pcm: SILENCE },
  press: { sampleRate: 48000, pcm: SILENCE },
} as const

export { soundSamples }
